package io.github.jesterportfolio.hearth.survival.housing;

import java.util.*;
import java.util.function.*;
import org.bukkit.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.inventory.*;
import net.kyori.adventure.text.Component;
import io.github.jesterportfolio.hearth.economy.EconomyReport;
import io.github.jesterportfolio.hearth.survival.economy.NativeMenuRules;
import static io.github.jesterportfolio.hearth.survival.housing.HousingState.*;

/** /월드의 개인 거주 진입에서 구매/확장·초대/수락·구획을 한 흐름으로 제공합니다. */
public final class HousingMenu implements Listener,AutoCloseable {
 private final HousingRuntime h;private final Map<UUID,Object> pending=new HashMap<>();private boolean closed;
 private final class Screen implements InventoryHolder{final Player player;final Object token;final long generation;final Inventory inventory;final Map<Integer,Runnable> actions=new HashMap<>();Screen(Player p,String title){player=p;token=h.boundary.token(p);generation=h.generation();inventory=Bukkit.createInventory(this,54,Component.text(title));}public Inventory getInventory(){return inventory;}}
 public HousingMenu(HousingRuntime h){this.h=h;Bukkit.getPluginManager().registerEvents(this,h.plugin);}
 private boolean current(Screen s){return !closed&&h.ready(s.player)&&h.boundary.current(s.player,s.token)&&s.generation==h.generation()&&s.player.getOpenInventory().getTopInventory()==s.inventory;}
 private void button(Screen s,int slot,Material icon,String title,Runnable action,String... lines){var item=new ItemStack(icon);item.editMeta(meta->{meta.displayName(Component.text(title));meta.lore(Arrays.stream(lines).map(Component::text).toList());});s.inventory.setItem(slot,item);if(action!=null)s.actions.put(slot,action);}
 private void show(Screen s){if(h.ready(s.player))s.player.openInventory(s.inventory);}
 private String name(UUID id){String n=Bukkit.getOfflinePlayer(id).getName();return n==null?"등록 사용자 "+id.toString().substring(0,8):n;}
 public void home(Player p){if(!h.ready(p))return;Object token=h.boundary.token(p);Object request=new Object();pending.put(p.getUniqueId(),request);var origin=p.getOpenInventory().getTopInventory();h.store.players(h.economy.context(p)).thenComposeAsync(players->{h.updatePlayers(players);return h.economy.store.account(h.economy.context(p));},h.owner).whenCompleteAsync((account,error)->{if(closed||pending.get(p.getUniqueId())!=request||!h.ready(p)||!h.boundary.current(p,token)||p.getOpenInventory().getTopInventory()!=origin)return;pending.remove(p.getUniqueId());if(error!=null){p.sendMessage(Component.text("거주 정보를 불러오지 못했습니다."));return;}var s=new Screen(p,"거주 · 내 집과 함께 사는 집");button(s,4,Material.EMERALD,"보유 화폐: "+account.balance(),null);var mine=h.snapshot().owned(p.getUniqueId());if(mine.isEmpty())button(s,10,Material.GRASS_BLOCK,"개인 거주 월드 구매",()->tiers(p,null,account.balance()),h.settings.purchases()?"크기와 금액을 확인한 뒤 구매":"가격 설정 후 구매를 열 예정입니다.");else{var own=mine.get();button(s,10,Material.OAK_DOOR,"나의 집",own.phase()==Phase.ACTIVE?()->details(p,own):null,"크기: "+own.width()+" × "+own.width(),own.phase()==Phase.ACTIVE?"이동·확장·초대 관리":"준비/결제 결과 보류 · 원본 보존 중");}button(s,12,Material.PLAYER_HEAD,"함께 사는 집",()->shared(p,0,false));button(s,14,Material.PAPER,"받은 초대",()->shared(p,0,true));boolean plot=h.snapshot().plots().containsKey(p.getUniqueId());button(s,16,Material.OAK_FENCE,plot?"기본 거주 구획으로 이동":"기본 거주 구획 배정",plot?()->h.plot(p):()->confirm(p,"무료 구획 배정",List.of("공용 거주의 제한된 구획을 계정당 하나 배정합니다."),()->h.claim(p)));show(s);},h.owner);}
 private void details(Player p,House house){var s=new Screen(p,name(house.owner())+"의 집");button(s,10,Material.OAK_DOOR,"집으로 이동",()->h.enter(p,house),"크기: "+house.width()+" × "+house.width());if(house.owner().equals(p.getUniqueId())){button(s,12,Material.GRASS_BLOCK,"크기 확장",()->tiers(p,house,-1),"기존 건축물 유지 · 등급 차액만 결제");button(s,14,Material.PLAYER_HEAD,"거주자·방문자 관리",()->members(p,house,0));button(s,16,Material.NAME_TAG,"사람 초대",()->candidates(p,house,0));button(s,31,Material.COMPASS,"현재 위치를 집 입장점으로",()->h.setHome(p,house),"집 경계 안의 안전한 위치에서 지정하세요.");}else button(s,31,Material.BARRIER,"이 집에서 탈퇴",()->confirm(p,"공동 거주 탈퇴",List.of("개인 가방은 유지되며 이 집 접근 권한을 해제합니다."),()->h.remove(p,house,p.getUniqueId())));button(s,45,Material.ARROW,"거주 홈",()->home(p));show(s);}
 private void tiers(Player p,House house,long knownBalance){if(knownBalance<0){var token=h.boundary.token(p);var origin=p.getOpenInventory().getTopInventory();long generation=h.generation();h.economy.store.account(h.economy.context(p)).whenCompleteAsync((a,e)->{if(e==null&&h.ready(p)&&h.boundary.current(p,token)&&p.getOpenInventory().getTopInventory()==origin&&generation==h.generation())tiers(p,house,a.balance());},h.owner);return;}var catalog=house==null?h.settings.catalog():h.snapshot().catalogs().get(house.version());var s=new Screen(p,house==null?"개인 월드 구매":"개인 월드 확장");int start=house==null?0:house.tier()+1;for(int i=start;i<catalog.tiers().size();i++){final int target=i;var tier=catalog.tiers().get(i);long cost=catalog.cost(house==null?-1:house.tier(),i);button(s,10+(i-start),Material.GRASS_BLOCK,tier.width()+" × "+tier.width(),h.settings.purchases()&&knownBalance>=cost?()->confirm(p,house==null?"월드 구매 최종 확인":"확장 최종 확인",List.of("크기: "+tier.width()+" × "+tier.width(),"결제: "+cost,"잔액: "+knownBalance+" → "+(knownBalance-cost),"유지비 없음 · 기존 건축물 보존"),()->h.purchase(p,target,house==null?-1:house.revision(),UUID.randomUUID())):null,"결제: "+cost,"잔액: "+knownBalance,h.settings.purchases()?(knownBalance>=cost?"클릭하여 최종 확인":"화폐가 부족합니다."):"구매가 아직 열리지 않았습니다.");}if(start>=catalog.tiers().size())button(s,22,Material.BARRIER,"최대 크기입니다.",null);button(s,45,Material.ARROW,"거주 홈",()->home(p));show(s);}
 private void confirm(Player p,String title,List<String> lines,Runnable action){var s=new Screen(p,title);button(s,13,Material.PAPER,title,null,lines.toArray(String[]::new));button(s,31,Material.LIME_DYE,"확정",action);button(s,45,Material.ARROW,"취소",()->home(p));show(s);}
 private <T>void rows(Player p,String title,List<T> all,int page,BiConsumer<Screen,List<T>> render,IntConsumer next){var s=new Screen(p,title);render.accept(s,EconomyReport.page(all,page));if(page>0)button(s,48,Material.ARROW,"이전",()->next.accept(page-1));if((page+1)*45<all.size())button(s,53,Material.ARROW,"다음",()->next.accept(page+1));button(s,45,Material.ARROW,"거주 홈",()->home(p));show(s);}
 private void shared(Player p,int page,boolean invited){var list=h.snapshot().members().stream().filter(m->m.player().equals(p.getUniqueId())&&m.accepted()!=invited).toList();rows(p,invited?"받은 초대":"함께 사는 집",list,page,(s,items)->{int slot=0;for(var m:items){var house=h.house(m.house()).orElseThrow();button(s,slot++,Material.OAK_DOOR,name(house.owner())+"의 집",()->{if(!invited)details(p,house);else{var dialog=new Screen(p,"집 초대 · 수락 또는 거절");button(dialog,13,Material.PAPER,name(house.owner())+"의 초대",null,m.role()==Role.RESIDENT?"입장·건축·보관함 공유":"입장만 가능 · 변경/보관함 사용 불가");button(dialog,29,Material.LIME_DYE,"수락",()->h.accept(p,house,true));button(dialog,33,Material.RED_DYE,"거절",()->h.accept(p,house,false));show(dialog);}},m.role()==Role.RESIDENT?"거주자":"방문자");}},n->shared(p,n,invited));}
 private void candidates(Player p,House house,int page){var existing=h.snapshot().members().stream().filter(m->m.house().equals(house.id())).map(Member::player).collect(java.util.stream.Collectors.toSet());var list=h.snapshot().players().stream().filter(id->!id.equals(p.getUniqueId())&&!existing.contains(id)).toList();rows(p,"초대할 등록 사용자",list,page,(s,items)->{int slot=0;for(var id:items)button(s,slot++,Material.PLAYER_HEAD,name(id),()->{var next=new Screen(p,"초대 권한 선택");button(next,20,Material.OAK_DOOR,"거주자로 초대",()->h.invite(p,house,id,Role.RESIDENT),"함께 건축하고 보관함/시설을 공유합니다.");button(next,24,Material.GLASS,"방문자로 초대",()->h.invite(p,house,id,Role.VISITOR),"입장만 허용하며 변경/보관함 사용은 막습니다.");show(next);});},n->candidates(p,house,n));}
 private void members(Player p,House house,int page){var list=h.snapshot().members().stream().filter(m->m.house().equals(house.id())).toList();rows(p,"거주자·초대 관리",list,page,(s,items)->{int slot=0;for(var m:items)button(s,slot++,Material.PLAYER_HEAD,name(m.player()),()->confirm(p,"거주 권한 해제",List.of("대상: "+name(m.player()),"개인 가방/잔액은 삭제하지 않습니다."),()->h.remove(p,house,m.player())),m.accepted()?"수락됨":"초대 대기",m.role()==Role.RESIDENT?"거주자":"방문자");},n->members(p,house,n));}
 @EventHandler(priority=EventPriority.HIGHEST) public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof HousingMenu.Screen s))return;boolean denied=e.isCancelled();e.setCancelled(true);if(!NativeMenuRules.allow(e.getWhoClicked()==s.player&&current(s),denied,e.getClickedInventory()==s.inventory,s.player.getItemOnCursor().isEmpty(),e.getClick().name(),false))return;var action=s.actions.get(e.getSlot());if(action!=null)Bukkit.getScheduler().runTask(h.plugin,()->{if(current(s))action.run();});}
 @EventHandler(priority=EventPriority.HIGHEST) public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof HousingMenu.Screen)e.setCancelled(true);}
 public void invalidate(UUID player){pending.remove(player);}
 @Override public void close(){closed=true;pending.clear();HandlerList.unregisterAll(this);}
}
